package mrpapermoon.whisper.serviceimport android.content.Contextimport androidx.annotation.CallSuperimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Deferredimport kotlinx.coroutines.awaitCancellationimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.FlowCollectorimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.emitAllimport kotlinx.coroutines.launchimport kotlinx.coroutines.sync.Muteximport kotlinx.coroutines.sync.withLockimport mrpapermoon.whisper.service.internal.NearbyConnectionsAdapterImplimport java.util.concurrent.CopyOnWriteArrayListimport java.util.concurrent.atomic.AtomicBooleanabstract class NearbyConnectionsAdapter internal constructor(	private val emitScope: CoroutineScope,	protected val uuid: String,) : Flow<NearbyConnectionEvent> {	abstract val activeEndpoints: List<String>	abstract val ignoreEndpoints: List<String>	private val collectors = CopyOnWriteArrayList<FlowCollector<NearbyConnectionEvent>>()	private val isStarted = AtomicBoolean(false)	private val startStopLocker = Mutex()	abstract suspend fun sendPayloadBytes(endpointId: String, byteArray: ByteArray)	suspend fun startConnection() {		if (!isStarted.getAndSet(true)) {			startStopLocker.withLock {				startAdvertising().await()				startDiscovery().await()			}		}	}	@CallSuper	open suspend fun stopAllConnections() {		startStopLocker.withLock {			isStarted.set(false)			collectors.clear()		}	}	final override suspend fun collect(collector: FlowCollector<NearbyConnectionEvent>) {		collectors += collector		startConnection()		try {			awaitCancellation()		} finally {			collectors -= collector			if (collectors.isEmpty()) {				stopAllConnections()			}		}	}	protected abstract fun startDiscovery(): Deferred<Void>	protected abstract fun startAdvertising(): Deferred<Void>	protected fun emitFlatten(eventFlow: Flow<NearbyConnectionEvent>) {		emitScope.launch {			for (collector in collectors) {				collector.emitAll(eventFlow)			}		}	}	protected infix fun FlowCollector<NearbyConnectionEvent>.emitEvent(event: NearbyConnectionEvent) {		emitScope.launch {			this@emitEvent.emit(event)		}	}	protected infix fun FlowCollector<NearbyConnectionEvent>.emitEventSource(eventFlow: Flow<NearbyConnectionEvent>) {		emitScope.launch {			this@emitEventSource.emitAll(eventFlow)		}	}	companion object Factory {		protected const val SERVICE_ID = "mrpapermoon.whisper.MESH_SERVICE"		fun collectFlatten(			context: Context,			scope: CoroutineScope,			uuid: String,			collector: FlowCollector<NearbyConnectionEvent>,		) {			val adapterImpl = NearbyConnectionsAdapterImpl(context, scope, uuid)			scope.launch {				adapterImpl.collect(collector)			}		}		fun getBuffered(			context: Context,			extraBufferCapacity: Int,			scope: CoroutineScope,			uuid: String,		): Flow<NearbyConnectionEvent> {			val adapterImpl = NearbyConnectionsAdapterImpl(context, scope, uuid)			val sharedFlow = MutableSharedFlow<NearbyConnectionEvent>(extraBufferCapacity = extraBufferCapacity)			scope.launch {				sharedFlow.emitAll(adapterImpl)			}			return sharedFlow		}		fun getConnectionsAdapter(			context: Context,			scope: CoroutineScope,			uuid: String,		): NearbyConnectionsAdapter = NearbyConnectionsAdapterImpl(context, scope, uuid)	}}